"use client"

import {
  ArrowDown01Icon,
  BlockGameIcon,
  BookOpen02Icon,
  BubbleChatIcon,
  Building02Icon,
  CallRinging04Icon,
  Chart03Icon,
  ChartColumnIcon,
  CodeIcon,
  DashboardBrowsingIcon,
  DashboardCircleIcon,
  Globe02Icon,
  GoogleDocIcon,
  Key01Icon,
  Message02Icon,
  PlayIcon,
  PlusSignIcon,
  Queue02Icon,
  RoboticIcon,
  Settings01Icon,
  ShieldKeyIcon,
  SmartPhone01Icon,
  CpuIcon,
  TaskDaily01Icon,
  TelephoneIcon,
  VariableIcon,
  VoiceIcon,
  WebhookIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/icon"

/**
 * Icons for the shared product shell — one glyph per nav destination, matched
 * to the app's own sidebar. Icons *inside* a mockup live in that mockup's own
 * icons.tsx; this file is only the app chrome.
 */
export const PlaygroundIcon = icon(PlayIcon, "PlaygroundIcon")
export const PersonasIcon = icon(RoboticIcon, "PersonasIcon")
export const ScenariosIcon = icon(GoogleDocIcon, "ScenariosIcon")
export const KnowledgeIcon = icon(BookOpen02Icon, "KnowledgeIcon")
export const BatchCallsIcon = icon(Queue02Icon, "BatchCallsIcon")
export const TemplateIcon = icon(DashboardCircleIcon, "TemplateIcon")
export const GlobalPromptsIcon = icon(Globe02Icon, "GlobalPromptsIcon")
export const VoiceLibraryIcon = icon(VoiceIcon, "VoiceLibraryIcon")
export const DashboardIcon = icon(Chart03Icon, "DashboardIcon")
export const ConversationsIcon = icon(CallRinging04Icon, "ConversationsIcon")
export const MessagingIcon = icon(Message02Icon, "MessagingIcon")
export const QualityIcon = icon(DashboardBrowsingIcon, "QualityIcon")
export const ReportsIcon = icon(ChartColumnIcon, "ReportsIcon")
export const TasksIcon = icon(TaskDaily01Icon, "TasksIcon")
export const KeyIcon = icon(Key01Icon, "KeyIcon")
export const VariablesIcon = icon(VariableIcon, "VariablesIcon")
export const WebhooksIcon = icon(WebhookIcon, "WebhooksIcon")
export const IntegrationsIcon = icon(BlockGameIcon, "IntegrationsIcon")
export const DeveloperDocsIcon = icon(CodeIcon, "DeveloperDocsIcon")
export const BuildingIcon = icon(Building02Icon, "BuildingIcon")
export const RolesIcon = icon(ShieldKeyIcon, "RolesIcon")
export const MobileIcon = icon(SmartPhone01Icon, "MobileIcon")
/* The model catalog (DES-169), under Configuration. */
export const ModelsIcon = icon(CpuIcon, "ModelsIcon")
export const TelephonyIcon = icon(TelephoneIcon, "TelephonyIcon")
export const SettingsIcon = icon(Settings01Icon, "SettingsIcon")
export const MessagingSettingsIcon = icon(
  BubbleChatIcon,
  "MessagingSettingsIcon",
)
export const ChevronDownIcon = icon(ArrowDown01Icon, "ChevronDownIcon")
/** The hover "+" on Personas and Scenarios — creates one without leaving the nav. */
export const NewItemIcon = icon(PlusSignIcon, "NewItemIcon")

"use client"

import Image from "next/image"
import * as React from "react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"
import {
  BatchCallsIcon,
  BuildingIcon,
  ChevronDownIcon,
  ConversationsIcon,
  DashboardIcon,
  DeveloperDocsIcon,
  GlobalPromptsIcon,
  IntegrationsIcon,
  KeyIcon,
  KnowledgeIcon,
  MessagingIcon,
  MessagingSettingsIcon,
  MobileIcon,
  ModelsIcon,
  NewItemIcon,
  PersonasIcon,
  PlaygroundIcon,
  QualityIcon,
  ReportsIcon,
  RolesIcon,
  ScenariosIcon,
  SettingsIcon,
  TasksIcon,
  TelephonyIcon,
  TemplateIcon,
  VariablesIcon,
  VoiceLibraryIcon,
  WebhooksIcon,
} from "@/components/app-shell-icons"

/**
 * The app around any mockup screen, shared by every mockup that wants the
 * product chrome: an inset sidebar over a tinted page, and a header carrying
 * the breadcrumb and the account. Pass `active` to highlight the nav item the
 * screen lives under.
 *
 * Playground sits above the groups rather than inside one — it is the entry
 * point, not a build step. Configuration starts closed because it is the group
 * you visit once and then leave alone.
 */

interface NavItem {
  /** Label for the hover "+", on the two things you create most. */
  action?: string
  icon: React.ComponentType
  title: string
}

const PLAYGROUND: NavItem = { icon: PlaygroundIcon, title: "Playground" }

const NAV: { defaultOpen: boolean; items: NavItem[]; label: string }[] = [
  {
    defaultOpen: true,
    label: "Agents",
    items: [
      { action: "New persona", icon: PersonasIcon, title: "Personas" },
      { action: "New scenario", icon: ScenariosIcon, title: "Scenarios" },
      { icon: KnowledgeIcon, title: "Knowledge Bases" },
      { icon: BatchCallsIcon, title: "Batch Calls" },
      { icon: TemplateIcon, title: "Scenario Templates" },
      { icon: GlobalPromptsIcon, title: "Global Prompts" },
      { icon: VoiceLibraryIcon, title: "Voice Library" },
    ],
  },
  {
    defaultOpen: true,
    label: "Monitor",
    items: [
      { icon: DashboardIcon, title: "Dashboard" },
      { icon: ConversationsIcon, title: "Conversations" },
      { icon: MessagingIcon, title: "Messaging" },
      { icon: QualityIcon, title: "Quality Dashboard" },
      { icon: ReportsIcon, title: "Reports" },
      { icon: TasksIcon, title: "Tasks" },
    ],
  },
  {
    defaultOpen: false,
    label: "Configuration",
    items: [
      { icon: KeyIcon, title: "API Keys" },
      { icon: VariablesIcon, title: "Variables" },
      { icon: WebhooksIcon, title: "Webhooks" },
      { icon: IntegrationsIcon, title: "Integrations" },
      { icon: DeveloperDocsIcon, title: "Developer Docs" },
      { icon: BuildingIcon, title: "Organizations" },
      /* DES-170. Roles are platform-wide and Sarj-only in Phase 1, so they sit
         beside Organizations rather than inside one. */
      { icon: RolesIcon, title: "Roles" },
      { icon: MobileIcon, title: "Phone Numbers" },
      /* DES-169. The catalog needs a home in the nav, and Configuration is
         where the other platform-wide, Sarj-staff-only surfaces already sit. */
      { icon: ModelsIcon, title: "Models" },
      { icon: TelephonyIcon, title: "Telephony" },
      { icon: SettingsIcon, title: "Global Settings" },
      { icon: MessagingSettingsIcon, title: "Messaging Settings" },
    ],
  },
]

function NavLink({
  active,
  item,
  onNavigate,
}: {
  active: boolean
  item: NavItem
  onNavigate?: (title: string) => void
}) {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        isActive={active}
        tooltip={item.title}
        onClick={() => onNavigate?.(item.title)}
      >
        <item.icon />
        <span className="truncate">{item.title}</span>
      </SidebarMenuButton>
      {/* `rounded-sm` in place of the primitive's `rounded-md` and `right-2` in
          place of `right-1`, both as the app has them.

          The glyph size is deliberately NOT the app's `[&>svg]:size-full`. That
          class works there because its plus is a hand-drawn 20×20 icon whose
          path spans only 6.5→13.5, so filling the box still draws a 7px plus.
          Ours is HugeIcons' PlusSignIcon, whose ink fills 16 of its 24 viewBox
          units — the same class drew a 12px plus, nearly twice the app's.
          `size-2.5` renders it at 10px, putting the drawn plus at 6.7px. */}
      {item.action ? (
        <SidebarMenuAction
          aria-label={item.action}
          className="top-1.5 right-2 rounded-sm border border-input bg-background text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-2.5"
        >
          <NewItemIcon />
        </SidebarMenuAction>
      ) : null}
    </SidebarMenuItem>
  )
}

/**
 * Collapsed to the icon rail there is no room for a section label, so the
 * groups are forced open and the label — the only thing that could close them —
 * is disabled.
 */
function NavGroup({
  active,
  defaultOpen,
  items,
  label,
  onNavigate,
}: {
  active: string
  defaultOpen: boolean
  items: NavItem[]
  label: string
  onNavigate?: (title: string) => void
}) {
  const { state } = useSidebar()
  const isCollapsed = state === "collapsed"
  const [open, setOpen] = React.useState(defaultOpen)

  return (
    <Collapsible
      disabled={isCollapsed}
      onOpenChange={isCollapsed ? undefined : setOpen}
      open={isCollapsed || open}
    >
      <SidebarGroup>
        <SidebarGroupLabel asChild>
          <CollapsibleTrigger className="flex w-full cursor-pointer items-center justify-between hover:bg-accent/50">
            <span>{label}</span>
            <ChevronDownIcon
              className={cn(
                "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
                open ? "rotate-0" : "-rotate-90",
              )}
            />
          </CollapsibleTrigger>
        </SidebarGroupLabel>
        <CollapsibleContent>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <NavLink
                  active={item.title === active}
                  item={item}
                  key={item.title}
                  onNavigate={onNavigate}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </CollapsibleContent>
      </SidebarGroup>
    </Collapsible>
  )
}

/** Breadcrumb start, account end — the row every page in the app sits under. */
function AppHeader({
  breadcrumb,
  showSettings,
}: {
  breadcrumb: string
  showSettings: boolean
}) {
  return (
    <header className="flex h-16 shrink-0 items-center justify-between gap-4 px-4">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink href="#">Home</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>{breadcrumb}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        <Button size="sm" variant="outline">
          <DeveloperDocsIcon />
          Developer Doc
        </Button>
        {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
        {showSettings ? (
          <Button aria-label="Global settings" size="icon-sm" variant="outline">
            <SettingsIcon />
          </Button>
        ) : null}
        {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
        <div className="flex items-center">
          <Separator className="mx-1 h-4" orientation="vertical" />
        </div>
        {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
        <Avatar className="size-7 rounded-lg after:rounded-lg">
          <AvatarFallback className="rounded-lg">TA</AvatarFallback>
        </Avatar>
      </div>
    </header>
  )
}

export function AppShell({
  active,
  breadcrumb,
  hiddenItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** Page label in the breadcrumb; defaults to `active`. */
  breadcrumb?: string
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items.filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    <SidebarProvider className="min-h-0 flex-1">
      {/* The sidebar pins to the viewport as it does in the app, so it clears
          the mockup shell's own header rather than sliding under it. */}
      <Sidebar className="pt-12" collapsible="icon" variant="inset">
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="text-muted-foreground" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          breadcrumb={breadcrumb ?? active}
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="flex min-h-0 flex-1 flex-col overflow-auto">
          {children}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"
import {
  CONFIGURED_ALERTS,
  SEVERITY_ORDER,
  type AlertAnalysis,
  type Detection,
} from "@/lib/behavioral-alerts-data"
import { ScenarioSettingsIcon } from "@/components/behavioral-alerts/icons"
import { formatTimeSeconds } from "@/components/behavioral-alerts/recording-player"
import { Seekable } from "@/components/behavioral-alerts/seekable"
import {
  SEVERITY_RULE,
  SeverityBadge,
} from "@/components/behavioral-alerts/severity"

/**
 * What the post-call analyst found, as the panel's own section.
 *
 * The three "nothing fired" cases are three different messages rather than one
 * blank panel — "no flag was detected", "no flag is configured" and "this
 * call was never analysed" are three different things to do next.
 */
export function AlertDetectionsBody({
  analysis,
  onConfigureAlerts,
  onSeek,
}: {
  analysis: AlertAnalysis
  /** Opens the scenario the alerts would be configured on. */
  onConfigureAlerts: () => void
  onSeek: (seconds: number) => void
}) {
  if (analysis.state === "pending") {
    return (
      <p className="flex items-center gap-2 text-sm text-muted-foreground">
        <Spinner className="size-4 shrink-0" />
        Analysing this call. Detections appear here when the post-call task
        finishes.
      </p>
    )
  }

  if (analysis.state === "unavailable") {
    return (
      <p className="text-sm text-muted-foreground">
        The call ended before anything was said, so there was no transcript to
        analyse.
      </p>
    )
  }

  if (analysis.state === "unconfigured") {
    return (
      <>
        <p className="text-sm text-muted-foreground">
          This scenario has no flags configured, so nothing was watched for.
        </p>
        <Button
          className="self-start"
          onClick={onConfigureAlerts}
          size="sm"
          variant="outline"
        >
          <ScenarioSettingsIcon />
          Configure flags
        </Button>
      </>
    )
  }

  if (analysis.detections.length === 0) {
    return (
      <p className="text-sm text-muted-foreground">
        No configured flag was detected on this call.
      </p>
    )
  }

  const detections = [...analysis.detections].sort(
    (a, b) =>
      SEVERITY_ORDER.indexOf(a.severity) - SEVERITY_ORDER.indexOf(b.severity),
  )

  return (
    <div className="flex flex-col gap-2">
      {detections.map((detection) => (
        <DetectionRow
          detection={detection}
          key={detection.id}
          onSeek={onSeek}
        />
      ))}
    </div>
  )
}

/** The label the collapsed section header carries, per state. */
export function detectionsSummary(analysis: AlertAnalysis) {
  if (analysis.state === "pending") return "Analysing"
  if (analysis.state === "unavailable") return "No transcript"
  if (analysis.state === "unconfigured") return "None configured"
  if (analysis.detections.length === 0) return "None detected"
  return `${analysis.detections.length} detected`
}

/**
 * One detection, and it seeks.
 *
 * The quote sits on its own surface and the explanation does not, because they
 * carry different weight: one is what the caller said and can be checked
 * against the transcript, the other is the model's reading of it. Rendered as
 * two equal paragraphs a reader has no way to tell which is which — and telling
 * them apart is the entire reason the PRD makes evidence mandatory.
 *
 * Which is also why the row is clickable: pressing it puts the playhead on the
 * quote and brings that turn up in the transcript beside it.
 */
function DetectionRow({
  detection,
  onSeek,
}: {
  detection: Detection
  onSeek: (seconds: number) => void
}) {
  const alert = CONFIGURED_ALERTS.find((item) => item.id === detection.alertId)

  return (
    <Seekable
      /* No hover tint. The card sits still; the pointer and the focus ring
         are what say it is pressable. */
      className="flex gap-3 rounded-lg bg-card p-3"
      label={`Seek to ${formatTimeSeconds(detection.at)}`}
      onActivate={() => {
        onSeek(detection.at)
      }}
    >
      {/* Severity twice, deliberately: the rule is what a reader sorts the
          list by at a glance, the badge is what they read. */}
      <span
        aria-hidden
        className={cn(
          "w-0.5 shrink-0 rounded-sm",
          SEVERITY_RULE[detection.severity],
        )}
      />

      <div className="flex min-w-0 flex-1 flex-col gap-2">
        <div className="flex items-start justify-between gap-2">
          <span className="text-sm font-medium text-foreground">
            {alert?.name ?? detection.alertId}
          </span>
          <SeverityBadge severity={detection.severity} />
        </div>

        <blockquote className="rounded-lg bg-muted p-2">
          <p className="text-sm text-foreground" dir="auto">
            &ldquo;{detection.evidence}&rdquo;
          </p>
          <span className="text-xs text-muted-foreground tabular-nums">
            {formatTimeSeconds(detection.at)}
          </span>
        </blockquote>

        <p className="text-sm text-muted-foreground">{detection.explanation}</p>
      </div>
    </Seekable>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Field, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import {
  PRIORITY_LABELS,
  PRIORITY_ORDER,
  type AlertPriority,
  type ConfiguredAlert,
} from "@/lib/behavioral-alerts-data"

const DESCRIPTION_LIMIT = 500

/**
 * Adding or editing one alert. Four fields, which is the whole definition — the
 * PRD's target is a client defining their own alerts in under two minutes.
 *
 * No helper text under any of them. Description is the one field whose job is
 * not obvious from its label, and a placeholder showing a real alert does that
 * better than a sentence explaining it would: the format is the example.
 */
export function AlertFormDialog({
  alert,
  onOpenChange,
  onSave,
  open,
}: {
  /** The alert being edited, or null when this is a new one. */
  alert: ConfiguredAlert | null
  onOpenChange: (open: boolean) => void
  onSave: (alert: ConfiguredAlert) => void
  open: boolean
}) {
  /* Seeded once, from whichever alert is being edited. The parent remounts this
     component every time it opens it — see the `key` on the call site — so the
     draft is fresh without an effect copying props into state on every open. */
  const [name, setName] = React.useState(alert?.name ?? "")
  const [description, setDescription] = React.useState(alert?.description ?? "")
  const [priority, setPriority] = React.useState<AlertPriority>(
    alert?.priority ?? "medium",
  )
  const [enabled, setEnabled] = React.useState(alert?.enabled ?? true)

  const complete = name.trim().length > 0 && description.trim().length > 0

  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{alert ? "Edit flag" : "Add flag"}</DialogTitle>
        </DialogHeader>

        <Field>
          <FieldLabel htmlFor="alert-name">Name</FieldLabel>
          <Input
            id="alert-name"
            onChange={(event) => {
              setName(event.target.value)
            }}
            placeholder="Escalation request"
            value={name}
          />
        </Field>

        <Field>
          <FieldLabel htmlFor="alert-description">Description</FieldLabel>
          <Textarea
            id="alert-description"
            maxLength={DESCRIPTION_LIMIT}
            onChange={(event) => {
              setDescription(event.target.value)
            }}
            placeholder="The caller asks to speak to a manager, a supervisor, or a human agent."
            rows={4}
            value={description}
          />
          <span className="text-xs text-muted-foreground tabular-nums">
            {description.length} / {DESCRIPTION_LIMIT}
          </span>
        </Field>

        <Field>
          <FieldLabel htmlFor="alert-priority">Priority</FieldLabel>
          <Select
            onValueChange={(value) => {
              setPriority(value as AlertPriority)
            }}
            value={priority}
          >
            <SelectTrigger id="alert-priority">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {PRIORITY_ORDER.map((level) => (
                <SelectItem key={level} value={level}>
                  {PRIORITY_LABELS[level]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>

        <Field orientation="horizontal">
          <FieldLabel htmlFor="alert-enabled">Enabled</FieldLabel>
          <Switch
            checked={enabled}
            id="alert-enabled"
            onCheckedChange={setEnabled}
          />
        </Field>

        <DialogFooter>
          <DialogClose asChild>
            <Button variant="ghost">Cancel</Button>
          </DialogClose>
          <Button
            disabled={!complete}
            onClick={() => {
              onSave({
                id: alert?.id ?? `alert-${name.trim().toLowerCase()}`,
                name: name.trim(),
                description: description.trim(),
                priority,
                enabled,
              })
            }}
          >
            {alert ? "Save changes" : "Add flag"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

