/**
 * The Call flags section on the scenario's Configuration tab, sitting
 * where Data extraction and Record sinks already sit — one card per thing the
 * scenario asks the post-call pipeline to do.
 *
 * A table rather than a card per alert: name, priority and on/off are three
 * short values that a client reads down a column to answer "what am I watching
 * for", and five cards each holding one sentence is a list in a costume.
 *
 * The whole row opens the alert, not just its name. A row that is clickable
 * only on one word is a row you have to aim at.
 */
export function ScenarioAlertsSection({
  alerts,
  onAlertsChange,
}: {
  alerts: ConfiguredAlert[]
  onAlertsChange: (alerts: ConfiguredAlert[]) => void
}) {
  const [editing, setEditing] = React.useState<ConfiguredAlert | null>(null)
  const [formOpen, setFormOpen] = React.useState(false)
  const [deleting, setDeleting] = React.useState<ConfiguredAlert | null>(null)
  /* Bumped on every open so the form remounts and seeds its draft from props.
     Editing the same alert twice has to start from the saved values both
     times, which a key on the alert's own id would not give. */
  const [formKey, setFormKey] = React.useState(0)
  /* The scenario either asks the post-call analyst to watch for flags or it
     does not, which is one switch above the list rather than five switches all
     turned off. Local, because it is this card's own setting — a call's
     analysis is already recorded and does not change when it flips. */
  const [watching, setWatching] = React.useState(true)

  function openNew() {
    setEditing(null)
    setFormKey((current) => current + 1)
    setFormOpen(true)
  }

  function openEdit(alert: ConfiguredAlert) {
    setEditing(alert)
    setFormKey((current) => current + 1)
    setFormOpen(true)
  }

  function save(alert: ConfiguredAlert) {
    onAlertsChange(
      alerts.some((item) => item.id === alert.id)
        ? alerts.map((item) => (item.id === alert.id ? alert : item))
        : [...alerts, alert],
    )
    setFormOpen(false)
  }

  function setEnabled(id: string, enabled: boolean) {
    onAlertsChange(
      alerts.map((item) => (item.id === id ? { ...item, enabled } : item)),
    )
  }

  return (
    <>
      <Card>
        <CardHeader>
          {/* Icon beside the title, the way every other section on the
              scenario page carries one. */}
          <CardTitle className="flex items-center gap-3">
            <FlagsIcon className="size-5 shrink-0" />
            Call flags
          </CardTitle>
          <CardDescription>
            Patterns the post-call analyst looks for in every transcript on this
            scenario.
          </CardDescription>
          <CardAction className="flex items-center gap-3">
            <Button
              disabled={!watching}
              onClick={openNew}
              size="sm"
              variant="outline"
            >
              <AddAlertIcon />
              Add flag
            </Button>
            <Switch
              aria-label="Watch for call flags on this scenario"
              checked={watching}
              onCheckedChange={setWatching}
            />
          </CardAction>
        </CardHeader>

        <CardContent>
          {alerts.length === 0 ? (
            <Empty>
              <EmptyHeader>
                <EmptyMedia variant="icon">
                  <FlagsIcon />
                </EmptyMedia>
                <EmptyTitle>No flags on this scenario</EmptyTitle>
                <EmptyDescription>
                  Calls still get a caller experience card. Add a flag to watch
                  for a pattern on top of it.
                </EmptyDescription>
              </EmptyHeader>
              <EmptyContent>
                <Button disabled={!watching} onClick={openNew}>
                  <AddAlertIcon />
                  Add flag
                </Button>
              </EmptyContent>
            </Empty>
          ) : (
            <ItemGroup className="gap-3">
              {alerts.map((alert) => (
                <Item
                  className={cn(
                    "items-start",
                    watching && "cursor-pointer hover:bg-muted/50",
                  )}
                  key={alert.id}
                  onClick={
                    watching
                      ? () => {
                          openEdit(alert)
                        }
                      : undefined
                  }
                  variant="outline"
                >
                  <ItemContent>
                    <ItemTitle className="flex-wrap gap-2">
                      {/* A paused flag keeps its definition and loses its
                          emphasis — the switch says it is off, the weight says
                          it stopped mattering to this list. */}
                      <span
                        className={cn(
                          (!watching || !alert.enabled) &&
                            "text-muted-foreground",
                        )}
                      >
                        {alert.name}
                      </span>
                      <PriorityBadge priority={alert.priority} />
                    </ItemTitle>
                    <ItemDescription>{alert.description}</ItemDescription>
                  </ItemContent>

                  <ItemActions
                    onClick={(event) => {
                      event.stopPropagation()
                    }}
                  >
                    <Switch
                      aria-label={`${alert.name} enabled`}
                      checked={alert.enabled}
                      disabled={!watching}
                      onCheckedChange={(checked) => {
                        setEnabled(alert.id, checked)
                      }}
                    />

                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          aria-label={`Actions for ${alert.name}`}
                          disabled={!watching}
                          size="icon-sm"
                          variant="ghost"
                        >
                          <RowMenuIcon />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem
                          onClick={() => {
                            openEdit(alert)
                          }}
                        >
                          <EditAlertIcon />
                          Edit
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => {
                            setDeleting(alert)
                          }}
                          variant="destructive"
                        >
                          <DeleteAlertIcon />
                          Delete
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </ItemActions>
                </Item>
              ))}
            </ItemGroup>
          )}
        </CardContent>
      </Card>

      <AlertFormDialog
        alert={editing}
        key={formKey}
        onOpenChange={setFormOpen}
        onSave={save}
        open={formOpen}
      />

      {/* Deleting throws the definition away and the detections already made
          against it stop having anything to name them. Pausing is the reason
          this dialog can offer a second way out rather than only a cancel. */}
      <AlertDialog
        onOpenChange={(open) => {
          if (!open) setDeleting(null)
        }}
        open={deleting !== null}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleting?.name}?</AlertDialogTitle>
            <AlertDialogDescription>
              Calls already analysed keep their detections. To stop detecting it
              without losing the definition, turn it off instead.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (!deleting) return
                onAlertsChange(alerts.filter((item) => item.id !== deleting.id))
                setDeleting(null)
              }}
              variant="destructive"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import { Switch } from "@/components/ui/switch"
import { cn } from "@/lib/utils"
import {
  OWNER,
  SENTIMENT_LABELS,
  type CallRow,
} from "@/lib/behavioral-alerts-data"
import {
  AlertDetectionsBody,
  detectionsSummary,
} from "@/components/behavioral-alerts/alert-detections"
import {
  FlagsIcon,
  CollectedIcon,
  CriterionMetIcon,
  CriterionMissedIcon,
  CustomizeIcon,
  DragHandleIcon,
  ExperienceIcon,
  GeneratedAtIcon,
  SectionToggleIcon,
  TechnicalIcon,
} from "@/components/behavioral-alerts/icons"
import { UserExperienceBody } from "@/components/behavioral-alerts/user-experience"

/**
 * The panel, as the revamped drawer has it: a register the reader owns rather
 * than a stack we chose for them.
 *
 * Sections keep arriving — this PRD adds two of them — and the order that suits
 * someone triaging frustrated callers is not the order that suits someone
 * auditing whether the workflow completed. So order and visibility are
 * settings, they are stored, and a section that is shut still states its
 * finding in its own header, which is what makes collapsing safe rather than
 * hostile.
 */

type SectionId = "alerts" | "collected" | "experience" | "outcome" | "technical"

/**
 * `open` is stored alongside order and visibility on purpose. Collapsing a
 * section in the panel and setting it to start collapsed are the same wish, so
 * they are the same flag — whichever way you set it, the section stays that way
 * on the next call.
 */
type Arrangement = { id: SectionId; open: boolean; visible: boolean }

const STORAGE_KEY = "sarj-mockup:behavioral-alerts-panel"

/**
 * The two the PRD adds lead, because they are the reading a client currently
 * cannot get anywhere. Technical is hidden outright — it is the rail nobody
 * read, and the header already prints the four fields off it that get used.
 */
const DEFAULT_ARRANGEMENT: Arrangement[] = [
  { id: "experience", open: true, visible: true },
  { id: "alerts", open: true, visible: true },
  { id: "outcome", open: false, visible: true },
  { id: "collected", open: false, visible: true },
  { id: "technical", open: false, visible: false },
]

/**
 * A stored arrangement is not trusted: it can predate a section being added or
 * renamed. Keep what is still known, in the stored order, then append anything
 * the defaults have that it does not.
 */
function normalise(stored: unknown): Arrangement[] {
  if (!Array.isArray(stored)) return DEFAULT_ARRANGEMENT

  const known = new Set(DEFAULT_ARRANGEMENT.map((item) => item.id))
  const kept: Arrangement[] = []

  for (const entry of stored) {
    const saved = entry as Arrangement | undefined
    const id = saved?.id
    if (!id || !known.has(id) || kept.some((item) => item.id === id)) continue
    kept.push({
      id,
      open: saved.open === true,
      visible: saved.visible !== false,
    })
  }

  for (const fallback of DEFAULT_ARRANGEMENT) {
    if (!kept.some((item) => item.id === fallback.id)) kept.push(fallback)
  }

  return kept
}

/* ---------------------------------------------------------- stored setting */

/**
 * The arrangement is state that lives outside React — localStorage owns it, and
 * it has to survive the drawer being closed and reopened, which unmounts every
 * component below. So it is read through `useSyncExternalStore` rather than
 * copied into state on mount: the server renders the defaults, the client
 * renders what is stored, and neither needs an effect to reconcile them.
 */
const listeners = new Set<() => void>()
let cachedRaw: string | null = null
let cachedValue = DEFAULT_ARRANGEMENT

function subscribe(listener: () => void) {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

function getSnapshot(): Arrangement[] {
  const raw = window.localStorage.getItem(STORAGE_KEY)

  if (raw !== cachedRaw) {
    cachedRaw = raw
    cachedValue = DEFAULT_ARRANGEMENT

    if (raw) {
      try {
        cachedValue = normalise(JSON.parse(raw))
      } catch {
        window.localStorage.removeItem(STORAGE_KEY)
        cachedRaw = null
      }
    }
  }

  return cachedValue
}

function getServerSnapshot(): Arrangement[] {
  return DEFAULT_ARRANGEMENT
}

function store(next: Arrangement[] | null) {
  if (next) window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next))
  else window.localStorage.removeItem(STORAGE_KEY)

  for (const listener of listeners) listener()
}

/* ----------------------------------------------------------- the register */

export function SectionRegister({
  call,
  onConfigureAlerts,
  onSeek,
}: {
  call: CallRow
  onConfigureAlerts: () => void
  onSeek: (seconds: number) => void
}) {
  const arrangement = React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    getServerSnapshot,
  )
  const anchors = React.useRef<Record<string, HTMLDivElement | null>>({})

  function setOpen(id: SectionId, open: boolean) {
    store(
      arrangement.map((item) => (item.id === id ? { ...item, open } : item)),
    )
  }

  function jumpTo(id: SectionId) {
    setOpen(id, true)
    anchors.current[id]?.scrollIntoView({
      behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "auto"
        : "smooth",
      block: "start",
    })
  }

  const sections = useSections(call, onConfigureAlerts, onSeek)
  /**
   * A section with nothing behind it on this call is absent, not empty: an
   * unanalysed call has no user experience to report, and a scenario that
   * extracts nothing has no collected data. A header that only ever says
   * "none" is a row the reader learns to skip.
   */
  const present = arrangement.filter((item) => sections[item.id] !== null)
  const shown = present.filter((item) => item.visible)

  return (
    <div className="flex h-full min-h-0 flex-col gap-3">
      {/* The chips wrap in their own box so the Customize button stays pinned
          beside them instead of being pushed onto a line of its own. */}
      <div className="flex shrink-0 items-start gap-2 border-b pb-3">
        <div className="flex flex-1 flex-wrap items-center gap-1">
          {shown.map((item) => (
            <Button
              className="font-normal"
              key={item.id}
              onClick={() => {
                jumpTo(item.id)
              }}
              size="xs"
              variant="ghost"
            >
              {sections[item.id]?.title}
            </Button>
          ))}
        </div>

        <CustomizePopover
          arrangement={present}
          onRearrange={(next) => {
            // Only the sections on this call are draggable, so the ones that
            // are absent keep their stored place rather than being appended.
            const order = next.map((item) => item.id)
            let cursor = 0
            store(
              arrangement.map((item) =>
                order.includes(item.id) ? next[cursor++] : item,
              ),
            )
          }}
          onReset={() => {
            store(null)
          }}
          sections={sections}
        />
      </div>

      <div className="scrollbar-hide flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto p-1">
        {shown.map((item) => {
          const section = sections[item.id]
          if (!section) return null

          return (
            <PanelSection
              icon={section.icon}
              isOpen={item.open}
              key={item.id}
              onToggle={() => {
                setOpen(item.id, !item.open)
              }}
              ref={(node) => {
                anchors.current[item.id] = node
              }}
              summary={section.summary}
              title={section.title}
            >
              {section.body}
            </PanelSection>
          )
        })}
      </div>
    </div>
  )
}

/* ------------------------------------------------------------- customizing */

function CustomizePopover({
  arrangement,
  onRearrange,
  onReset,
  sections,
}: {
  arrangement: Arrangement[]
  onRearrange: (next: Arrangement[]) => void
  onReset: () => void
  sections: Record<SectionId, null | Section>
}) {
  const [dragging, setDragging] = React.useState<SectionId | null>(null)
  /** Where the dragged row would land — the index the drop line sits before. */
  const [dropAt, setDropAt] = React.useState<number | null>(null)

  function move(from: number, to: number) {
    if (to < 0 || to >= arrangement.length || from === to) return
    const next = [...arrangement]
    const [moved] = next.splice(from, 1)
    next.splice(to, 0, moved)
    onRearrange(next)
  }

  /** Drop uses an insertion point, which shifts once the row is lifted out. */
  function moveTo(from: number, insertAt: number) {
    const next = [...arrangement]
    const [moved] = next.splice(from, 1)
    next.splice(insertAt > from ? insertAt - 1 : insertAt, 0, moved)
    onRearrange(next)
  }

  function set(id: SectionId, patch: Partial<Arrangement>) {
    onRearrange(
      arrangement.map((entry) =>
        entry.id === id ? { ...entry, ...patch } : entry,
      ),
    )
  }

  function endDrag() {
    setDragging(null)
    setDropAt(null)
  }

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          aria-label="Customize panel"
          className="shrink-0"
          size="icon-xs"
          variant="ghost"
        >
          <CustomizeIcon />
        </Button>
      </PopoverTrigger>

      <PopoverContent align="end" className="flex w-80 flex-col gap-3">
        <div className="flex flex-col gap-0.5">
          <span className="text-sm font-medium text-foreground">
            Customize panel
          </span>
          <span className="text-xs text-muted-foreground">
            Drag a section to reorder it. The switch takes it off the panel
            entirely.
          </span>
        </div>

        <div className="flex flex-col">
          {arrangement.map((item, index) => (
            <div
              className={cn(
                "relative flex items-center gap-2 rounded-lg py-1.5 pe-1 transition-opacity duration-150 ease-out-cubic motion-reduce:transition-none",
                dragging === item.id && "opacity-40",
              )}
              draggable
              key={item.id}
              onDragEnd={endDrag}
              onDragOver={(event) => {
                event.preventDefault()
                // Past the midpoint means it lands after this row, not before.
                const box = event.currentTarget.getBoundingClientRect()
                const below = event.clientY > box.top + box.height / 2
                setDropAt(below ? index + 1 : index)
              }}
              onDragStart={() => {
                setDragging(item.id)
              }}
              onDrop={() => {
                const from = arrangement.findIndex(
                  (entry) => entry.id === dragging,
                )
                if (from !== -1 && dropAt !== null) moveTo(from, dropAt)
                endDrag()
              }}
            >
              {/* The drop line is absolutely positioned so showing it does not
                  shove the rows around while you are still dragging. */}
              {dropAt === index ? <DropLine className="-top-px" /> : null}
              {dropAt === arrangement.length &&
              index === arrangement.length - 1 ? (
                <DropLine className="-bottom-px" />
              ) : null}

              {/* A button, not just the icon: dragging is the way to reorder,
                  and dragging has no keyboard equivalent — so the handle takes
                  arrow keys itself. */}
              <Button
                aria-label={`Reorder ${sections[item.id]?.title ?? item.id}`}
                className="shrink-0 cursor-grab"
                onKeyDown={(event) => {
                  if (event.key === "ArrowUp") {
                    event.preventDefault()
                    move(index, index - 1)
                  }
                  if (event.key === "ArrowDown") {
                    event.preventDefault()
                    move(index, index + 1)
                  }
                }}
                size="icon-xs"
                variant="ghost"
              >
                <DragHandleIcon />
              </Button>

              <span className="truncate text-sm text-foreground">
                {sections[item.id]?.title}
              </span>

              {/* Show only. "Open by default" was a second switch answering a
                  question the panel already answers by itself — collapsing a
                  section in the panel is stored, so the state it is in is the
                  state it starts in next time. */}
              <span className="ms-auto flex justify-center">
                <Switch
                  aria-label={`Show ${sections[item.id]?.title ?? item.id}`}
                  checked={item.visible}
                  onCheckedChange={(checked) => {
                    // Hiding a section also closes it, so bringing it back does
                    // not dump an expanded body into the panel unannounced.
                    set(item.id, {
                      open: checked ? item.open : false,
                      visible: checked,
                    })
                  }}
                />
              </span>
            </div>
          ))}
        </div>

        <Button
          className="self-end"
          onClick={onReset}
          size="sm"
          variant="ghost"
        >
          Reset
        </Button>
      </PopoverContent>
    </Popover>
  )
}

/** Where the dragged row will land. */
function DropLine({ className }: { className: string }) {
  return (
    <span
      className={cn(
        "pointer-events-none absolute inset-x-0 h-0.5 rounded-sm bg-primary",
        className,
      )}
    />
  )
}

/* ---------------------------------------------------------------- sections */

type Section = {
  body: React.ReactNode
  icon: React.ComponentType<{ className?: string }>
  /** What the header says while the section is shut. */
  summary: string
  title: string
}

function PanelSection({
  children,
  icon: Icon,
  isOpen,
  onToggle,
  ref,
  summary,
  title,
}: {
  children: React.ReactNode
  icon: React.ComponentType<{ className?: string }>
  isOpen: boolean
  onToggle: () => void
  ref: (node: HTMLDivElement | null) => void
  summary: string
  title: string
}) {
  return (
    <div className="flex scroll-mt-1 flex-col rounded-lg bg-muted" ref={ref}>
      <Button
        aria-expanded={isOpen}
        className="justify-start font-normal"
        onClick={onToggle}
        variant="ghost"
      >
        <Icon className="size-4 text-muted-foreground" />
        <span className="font-medium text-foreground">{title}</span>
        <span className="ms-auto text-xs text-muted-foreground">{summary}</span>
        <SectionToggleIcon
          className={cn(
            "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
            isOpen && "rotate-180",
          )}
        />
      </Button>

      {isOpen ? (
        <div className="flex flex-col gap-3 px-3 pb-3">{children}</div>
      ) : null}
    </div>
  )
}

/** `null` means this call has nothing for that section, so it is not drawn. */
function useSections(
  call: CallRow,
  onConfigureAlerts: () => void,
  onSeek: (seconds: number) => void,
): Record<SectionId, null | Section> {
  const journey = call.analysis.journey

  return {
    alerts: {
      body: (
        <AlertDetectionsBody
          analysis={call.analysis}
          onConfigureAlerts={onConfigureAlerts}
          onSeek={onSeek}
        />
      ),
      icon: FlagsIcon,
      summary: detectionsSummary(call.analysis),
      title: "Call flags",
    },
    collected: call.collected.length
      ? {
          body: <CollectedBody call={call} />,
          icon: CollectedIcon,
          summary: `${call.collected.length} fields`,
          title: "Collected data",
        }
      : null,
    experience: journey
      ? {
          body: <UserExperienceBody journey={journey} />,
          icon: ExperienceIcon,
          /* Sentiment and the rating together, because either one alone reads
             as the whole verdict — a five-star neutral call and a two-star
             neutral call are not the same call. */
          summary: `${SENTIMENT_LABELS[journey.sentiment]} · ${journey.rating}/5`,
          title: "Caller experience",
        }
      : null,
    outcome: {
      body: <OutcomeBody call={call} />,
      icon:
        call.outcome.status === "success"
          ? CriterionMetIcon
          : CriterionMissedIcon,
      /* The verdict, not the raw value — the collapsed header is the one place
         the reader sees it without opening the section. */
      summary: call.outcome.status === "success" ? "Achieved" : "Not achieved",
      title: "Call outcome",
    },
    technical: {
      body: <TechnicalBody call={call} />,
      icon: TechnicalIcon,
      summary: `${call.callId.slice(0, 8)}…`,
      title: "Technical",
    },
  }
}

/**
 * The scenario's own pass/fail and why — the reading the platform gives today,
 * kept beside the one this PRD adds rather than replaced by it.
 */
function OutcomeBody({ call }: { call: CallRow }) {
  const achieved = call.outcome.criteria.filter((item) => item.achieved).length

  return (
    <>
      <div className="flex flex-col gap-1">
        <span className="text-xs text-muted-foreground">Reason</span>
        <p className="text-sm leading-relaxed text-foreground">
          {call.outcome.reason}
        </p>
      </div>

      <div className="flex items-center gap-2 text-xs text-muted-foreground">
        <GeneratedAtIcon className="size-3.5" />
        Generated {call.endedAt}
      </div>

      <Separator />

      <div className="flex flex-col gap-2">
        <div className="flex items-baseline justify-between gap-2">
          <span className="text-xs text-muted-foreground">
            Success criteria
          </span>
          <span className="text-xs text-muted-foreground">
            {achieved} of {call.outcome.criteria.length} achieved
          </span>
        </div>

        {call.outcome.criteria.map((criterion) => (
          /* bg-card, not bg-muted: the section itself is already the muted
             surface, so a row has to come forward to read as a row. */
          <div
            className="flex items-start gap-2 rounded-lg bg-card p-3"
            key={criterion.text}
          >
            {criterion.achieved ? (
              <CriterionMetIcon className="mt-0.5 size-4 shrink-0 text-success" />
            ) : (
              <CriterionMissedIcon className="mt-0.5 size-4 shrink-0 text-destructive" />
            )}

            <span className="flex min-w-0 flex-col gap-0.5">
              <span className="text-sm text-foreground">{criterion.text}</span>
              <span className="text-xs text-muted-foreground">
                {criterion.achieved ? "Achieved" : "Not achieved"}
              </span>
            </span>

            {criterion.primary ? (
              <Badge className="ms-auto shrink-0" variant="outline">
                Primary
              </Badge>
            ) : null}
          </div>
        ))}
      </div>
    </>
  )
}

function CollectedBody({ call }: { call: CallRow }) {
  return (
    <div className="flex flex-col gap-2">
      {call.collected.map((field) => (
        <div
          className="flex items-baseline justify-between gap-4"
          key={field.label}
        >
          <span className="font-mono text-xs text-muted-foreground">
            {field.label}
          </span>
          <span className="text-sm font-medium text-foreground">
            {field.value}
          </span>
        </div>
      ))}
    </div>
  )
}

function TechnicalBody({ call }: { call: CallRow }) {
  const rows = [
    { label: "Call ID", value: call.callId },
    { label: "Created", value: call.createdAt },
    { label: "Started", value: call.startedAt },
    { label: "Ended", value: call.endedAt },
    { label: "User", value: OWNER.userId },
    { label: "Organization", value: OWNER.organizationId },
  ]

  return (
    <div className="flex flex-col gap-2">
      {rows.map((row) => (
        <div
          className="flex items-baseline justify-between gap-4"
          key={row.label}
        >
          <span className="text-xs text-muted-foreground">{row.label}</span>
          <span className="truncate text-xs text-foreground">{row.value}</span>
        </div>
      ))}
    </div>
  )
}

"use client"

import { cn } from "@/lib/utils"

/**
 * A clickable surface that is not a Button, ported from the revamped drawer.
 *
 * The transcript bubbles and the detection rows carry their own shape, and a
 * Button would fight its own padding and radius. Keyboard behaviour is the part
 * that has to be kept by hand.
 */
export function Seekable({
  children,
  className,
  label,
  onActivate,
}: {
  children: React.ReactNode
  className?: string
  label: string
  onActivate: () => void
}) {
  return (
    <div
      aria-label={label}
      className={cn(
        "cursor-pointer focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
        className,
      )}
      onClick={onActivate}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault()
          onActivate()
        }
      }}
      role="button"
      tabIndex={0}
    >
      {children}
    </div>
  )
}

"use client"

import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"
import {
  PRIORITY_LABELS,
  SENTIMENT_LABELS,
  SEVERITY_LABELS,
  type AlertPriority,
  type AlertSeverity,
  type Sentiment,
} from "@/lib/behavioral-alerts-data"

/**
 * The three colour-carrying chips on these screens, kept together so the two
 * three-step scales cannot drift apart in tone.
 *
 * Mild is deliberately NOT green. Severity says how bad this call was, and the
 * bottom of that scale is "worth knowing", not "good" — a green Mild next to a
 * red Severe reads as a pass/fail axis, which is the exact reading the whole
 * feature exists to stop the platform giving.
 */

const SEVERITY_TONE: Record<AlertSeverity, string> = {
  mild: "bg-muted text-muted-foreground",
  moderate: "bg-warning-tint text-warning-tint-foreground",
  severe: "bg-destructive-tint text-destructive-tint-foreground",
}

/** The rule down the start edge of a detection card, at full strength. */
export const SEVERITY_RULE: Record<AlertSeverity, string> = {
  mild: "bg-border",
  moderate: "bg-warning",
  severe: "bg-destructive",
}

/**
 * The dot on a call row in the list, at the same three strengths.
 *
 * Tinted by the worst thing detected rather than always red: a call whose only
 * detection is a Positive sentiment moment is marked, and a red dot on it would
 * say the opposite of what it found. Mild takes `muted-foreground` rather than
 * the rule's `border`, which at 8px on a white row is not there at all.
 */
export const SEVERITY_DOT: Record<AlertSeverity, string> = {
  mild: "bg-muted-foreground",
  moderate: "bg-warning",
  severe: "bg-destructive",
}

export function SeverityBadge({ severity }: { severity: AlertSeverity }) {
  return (
    <Badge className={SEVERITY_TONE[severity]}>
      {SEVERITY_LABELS[severity]}
    </Badge>
  )
}

/**
 * Priority is triage, not alarm — it orders the admin's own list and says
 * nothing about any particular call. So it is one outline chip with a dot that
 * changes, rather than three differently-coloured chips that would read as
 * three severities the moment they sit near a detection.
 *
 * One hue at three opacities rather than three chart slots. High, medium and
 * low are a rank, and DES-174 turned --chart-* into six unrelated hues — on
 * that palette these three dots would be blue, amber and violet, which is a
 * set, not a scale. Ordinal data gets one colour and less of it.
 */
const PRIORITY_DOT: Record<AlertPriority, string> = {
  high: "bg-primary",
  low: "bg-primary/30",
  medium: "bg-primary/60",
}

export function PriorityBadge({ priority }: { priority: AlertPriority }) {
  return (
    <Badge variant="outline">
      <span
        aria-hidden
        className={cn("size-1.5 rounded-4xl", PRIORITY_DOT[priority])}
      />
      {PRIORITY_LABELS[priority]}
    </Badge>
  )
}

const SENTIMENT_TONE: Record<Sentiment, string> = {
  angry: "bg-destructive-tint text-destructive-tint-foreground",
  frustrated: "bg-warning-tint text-warning-tint-foreground",
  neutral: "bg-muted text-muted-foreground",
  positive: "bg-success-tint text-success-tint-foreground",
}

export function SentimentBadge({ sentiment }: { sentiment: Sentiment }) {
  return (
    <Badge className={SENTIMENT_TONE[sentiment]}>
      {SENTIMENT_LABELS[sentiment]}
    </Badge>
  )
}

"use client"

import * as React from "react"

import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import { cn } from "@/lib/utils"
import type { AlertSeverity, CallRow } from "@/lib/behavioral-alerts-data"
import {
  AgentIcon,
  CallerIcon,
  ClearSearchIcon,
  NextMatchIcon,
  PrevMatchIcon,
  SearchIcon,
} from "@/components/behavioral-alerts/icons"
import {
  formatTimeSeconds,
  RecordingPlayer,
  type RecordingMarker,
} from "@/components/behavioral-alerts/recording-player"
import { Seekable } from "@/components/behavioral-alerts/seekable"
import { SeverityBadge } from "@/components/behavioral-alerts/severity"

/**
 * The left half of the revamped drawer: the recording, a search box, and the
 * turns.
 *
 * The one thing here that is not carried over unchanged is the evidence mark on
 * a turn. A detection promises a direct quote, and that promise is only
 * checkable if the reader can land on the line it came from — so the quoted
 * turn names the alert it triggered, and the detection in the panel seeks here.
 */

/** What a turn says about itself when a detection quoted it. */
export type Evidence = { name: string; severity: AlertSeverity }

export function TranscriptPanel({
  at,
  call,
  evidence,
  markers,
  onSeek,
}: {
  at: number
  call: CallRow
  /** Keyed by the turn's second, which is what a detection points at. */
  evidence: Map<number, Evidence>
  markers: RecordingMarker[]
  onSeek: (seconds: number) => void
}) {
  const [query, setQuery] = React.useState("")
  const [active, setActive] = React.useState(0)
  const turnRefs = React.useRef<Record<number, HTMLDivElement | null>>({})

  /** Every match in the transcript, in the order the turns are rendered. */
  const matches = React.useMemo(() => {
    const ranges = new Map<number, [number, number][]>()
    const offsets = new Map<number, number>()
    let total = 0

    call.transcript.forEach((line, index) => {
      const found = findMatches(line.text, query)
      ranges.set(index, found)
      offsets.set(index, total)
      total += found.length
    })

    return { offsets, ranges, total }
  }, [call.transcript, query])

  const search: Search = { ...matches, activeIndex: active }

  /** A shorter result list must not leave the cursor pointing past the end. */
  function runSearch(next: string) {
    setQuery(next)
    setActive(0)
  }

  function step(by: number) {
    if (!matches.total) return
    setActive((current) => (current + by + matches.total) % matches.total)
  }

  /**
   * Walking to a match moves the playhead too — the point of finding a line is
   * usually to hear it.
   */
  React.useEffect(() => {
    if (!matches.total) return

    const index = call.transcript.findIndex((_, turn) => {
      const offset = matches.offsets.get(turn) ?? 0
      const count = matches.ranges.get(turn)?.length ?? 0
      return active >= offset && active < offset + count
    })
    if (index === -1) return

    scrollTo(turnRefs.current[index])
    onSeek(call.transcript[index].at)
  }, [active, call.transcript, matches, onSeek])

  /**
   * Seeking from anywhere — the waveform, a marker, a detection in the panel —
   * brings the turn that was being spoken into view. Without it, clicking a
   * detection's quote moves a playhead the reader cannot see.
   */
  React.useEffect(() => {
    const index = activeTurn(call, at)
    if (index !== -1) scrollTo(turnRefs.current[index])
  }, [at, call])

  return (
    <div className="flex h-full min-h-0 flex-col gap-3 overflow-x-clip">
      <RecordingPlayer
        at={at}
        duration={call.duration}
        markers={markers}
        onSeek={onSeek}
      />

      <InputGroup className="shrink-0">
        <InputGroupAddon>
          <SearchIcon />
        </InputGroupAddon>
        <InputGroupInput
          onChange={(event) => {
            runSearch(event.target.value)
          }}
          onKeyDown={(event) => {
            if (event.key === "Escape") runSearch("")
            if (event.key === "Enter") {
              event.preventDefault()
              step(event.shiftKey ? -1 : 1)
            }
          }}
          placeholder="Search transcript"
          value={query}
        />
        {query ? (
          <InputGroupAddon align="inline-end">
            <span
              className={cn(
                "tabular-nums",
                search.total ? "text-muted-foreground" : "text-destructive",
              )}
            >
              {search.total ? `${active + 1} of ${search.total}` : "0"}
            </span>
            <InputGroupButton
              aria-label="Previous match"
              disabled={!search.total}
              onClick={() => {
                step(-1)
              }}
              size="icon-xs"
            >
              <PrevMatchIcon />
            </InputGroupButton>
            <InputGroupButton
              aria-label="Next match"
              disabled={!search.total}
              onClick={() => {
                step(1)
              }}
              size="icon-xs"
            >
              <NextMatchIcon />
            </InputGroupButton>
            <InputGroupButton
              aria-label="Clear search"
              onClick={() => {
                runSearch("")
              }}
              size="icon-xs"
            >
              <ClearSearchIcon />
            </InputGroupButton>
          </InputGroupAddon>
        ) : null}
      </InputGroup>

      {call.transcript.length === 0 ? (
        <p className="py-12 text-center text-sm text-muted-foreground">
          No transcript for this call.
        </p>
      ) : (
        <div className="scrollbar-hide flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto p-1">
          {call.transcript.map((line, index) => {
            const next = call.transcript[index + 1]

            return (
              <TurnRow
                evidence={evidence.get(line.at)}
                isPlaying={at >= line.at && (!next || at < next.at)}
                key={index}
                line={line}
                onSeek={onSeek}
                ref={(node) => {
                  turnRefs.current[index] = node
                }}
                search={search}
                turnIndex={index}
              />
            )
          })}
        </div>
      )}
    </div>
  )
}

/** Which turn was being spoken at a given second. */
function activeTurn(call: CallRow, at: number) {
  return call.transcript.findIndex((line, index) => {
    const next = call.transcript[index + 1]
    return at >= line.at && (!next || at < next.at)
  })
}

function scrollTo(node: HTMLDivElement | null) {
  node?.scrollIntoView({
    behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
      ? "auto"
      : "smooth",
    block: "center",
  })
}

function findMatches(text: string, query: string): [number, number][] {
  const needle = query.trim().toLowerCase()
  if (!needle) return []

  const haystack = text.toLowerCase()
  const found: [number, number][] = []
  let from = 0

  for (;;) {
    const index = haystack.indexOf(needle, from)
    if (index === -1) break
    found.push([index, index + needle.length])
    from = index + needle.length
  }

  return found
}

type Search = {
  /** Which hit the counter is pointing at, across every turn. */
  activeIndex: number
  offsets: Map<number, number>
  ranges: Map<number, [number, number][]>
  total: number
}

function TurnRow({
  evidence,
  isPlaying,
  line,
  onSeek,
  ref,
  search,
  turnIndex,
}: {
  evidence?: Evidence
  isPlaying: boolean
  line: CallRow["transcript"][number]
  onSeek: (seconds: number) => void
  ref: (node: HTMLDivElement | null) => void
  search: Search
  turnIndex: number
}) {
  const isCaller = line.speaker === "caller"

  return (
    <div
      className={cn("flex scroll-mt-1 gap-3", isCaller && "flex-row-reverse")}
      ref={ref}
    >
      <span
        className={cn(
          "flex size-8 shrink-0 items-center justify-center rounded-4xl",
          isCaller ? "bg-muted text-foreground" : "bg-primary/10 text-primary",
        )}
      >
        {isCaller ? (
          <CallerIcon className="size-4" />
        ) : (
          <AgentIcon className="size-4" />
        )}
      </span>

      <Seekable
        className={cn(
          "flex max-w-[80%] flex-col items-start gap-1 rounded-lg px-4 py-2.5 text-start transition-colors duration-150 ease-out-cubic motion-reduce:transition-none",
          isCaller
            ? "bg-primary text-primary-foreground hover:bg-primary-dark"
            : "bg-muted text-foreground hover:bg-accent",
          isPlaying && "ring-2 ring-primary",
        )}
        label={`Seek to ${formatTimeSeconds(line.at)}`}
        onActivate={() => {
          onSeek(line.at)
        }}
      >
        <span className="flex w-full items-center gap-2 text-xs opacity-70">
          {/* Same treatment as the Conversations drawer: the speaker is a label
              on the turn, not a word in it, and the caps keep it from reading
              as the first word of what was said. */}
          <span className="font-semibold tracking-wide uppercase">
            {isCaller ? "Customer" : "Agent"}
          </span>
          <span className="ms-auto tabular-nums">
            {formatTimeSeconds(line.at)}
          </span>
        </span>

        <span className="text-sm" dir="auto">
          <Highlighted search={search} text={line.text} turnIndex={turnIndex} />
        </span>

        {/* The line a detection quoted says which alert it triggered. The
            badge is the same one the detection carries in the panel, so the
            two ends of the claim are recognisably the same claim. */}
        {evidence ? (
          <span className="flex items-center gap-2 pt-1">
            <SeverityBadge severity={evidence.severity} />
            <span className="text-xs opacity-70">{evidence.name}</span>
          </span>
        ) : null}
      </Seekable>
    </div>
  )
}

/** Marks every hit, and the one the counter is currently pointing at. */
function Highlighted({
  search,
  text,
  turnIndex,
}: {
  search: Search
  text: string
  turnIndex: number
}) {
  const ranges = search.ranges.get(turnIndex)
  if (!ranges?.length) return text

  const offset = search.offsets.get(turnIndex) ?? 0
  const parts: React.ReactNode[] = []
  let cursor = 0

  ranges.forEach(([start, end], index) => {
    if (start > cursor) parts.push(text.slice(cursor, start))
    parts.push(
      <mark
        className={cn(
          "rounded-sm bg-warning/25 text-foreground",
          offset + index === search.activeIndex && "bg-primary/30",
        )}
        key={start}
      >
        {text.slice(start, end)}
      </mark>,
    )
    cursor = end
  })

  if (cursor < text.length) parts.push(text.slice(cursor))

  return parts
}

"use client"

import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  setToolbar,
  useToolbarEnabled,
  useToolbarSuppressed,
} from "@/components/staff-toolbar"
import { CommentIcon } from "@/components/workspace-icons"

/**
 * Turns Vercel Comments on for the mockup under it.
 *
 * The toolbar is opt-in — mounting it for everyone prompts *every* visitor to
 * log in to Vercel — but the opt-in used to be a query param you had to know
 * about, so a link sent without it was a dead end. This is that same switch
 * with an address: last in the shell header, identical on every mockup.
 *
 * It stays visible once the toolbar is up. The header is reviewer chrome
 * rather than part of the design being reviewed, and leaving it there is what
 * makes turning commenting back off something other than a typed URL.
 */
export function CommentToggle() {
  const enabled = useToolbarEnabled()
  const suppressed = useToolbarSuppressed()

  if (suppressed) return null

  /* The divider belongs to the toggle rather than to the header, so that
     hiding one for a screenshot cannot leave the other stranded. */
  return (
    <>
      <Separator
        orientation="vertical"
        className="h-5 data-vertical:self-center"
      />

      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            aria-label={
              enabled ? "Turn commenting off" : "Comment on this mockup"
            }
            aria-pressed={enabled}
            className={enabled ? undefined : "text-muted-foreground"}
            onClick={() => setToolbar(!enabled)}
            size="icon-sm"
            variant="ghost"
          >
            <CommentIcon />
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          {enabled ? "Turn commenting off" : "Comment on this mockup"}
        </TooltipContent>
      </Tooltip>
    </>
  )
}

"use client"

import type { ReactNode } from "react"

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  COLUMN_HELP,
  COLUMN_LABELS,
  type CallRow,
  type ColumnId,
  type ColumnSetting,
} from "@/lib/conversations-revamp-list-data"
import {
  AgentOutcomeBadge,
  DirectionChip,
  OutcomeBadge,
  ScenarioChip,
  StatusBadge,
} from "@/components/conversations-revamp/list/status-badges"
import { StatusHelp } from "@/components/conversations-revamp/list/status-help"
import { TimeIcon } from "@/components/conversations-revamp/list/icons"

/**
 * The table, driven by whatever the Fields dropdown says.
 *
 * Header and body both walk the same `columns` array, so a column cannot end up
 * in one and not the other, and reordering is a single list to move.
 */
export function CallTable({
  calls,
  columns,
  onCallClick,
  rowMarker,
}: {
  /** Owned by the page, because cancelling a scheduled call changes one. */
  calls: CallRow[]
  columns: ColumnSetting[]
  onCallClick: (call: CallRow) => void
  /**
   * A mark on the row's time icon, for a mockup whose calls carry a finding the
   * columns do not — the behavioural flags, in practice.
   *
   * It rides the icon rather than taking a column of its own: a column would
   * cost width on every row to say nothing on most of them, and this is the
   * absence of a value rather than a value. Rows with nothing to report return
   * null; the mockups that pass nothing get the table exactly as it was.
   */
  rowMarker?: (call: CallRow) => ReactNode
}) {
  const shown = columns.filter((column) => column.visible)

  return (
    <Table>
      <TableHeader>
        <TableRow className="bg-muted/50 hover:bg-muted/50">
          {shown.map((column) => (
            <TableHead
              className="font-semibold text-foreground"
              key={column.id}
            >
              {/* The help icon only appears on columns that carry a
                  COLUMN_HELP entry, so it marks the one header worth reading
                  rather than decorating every one of them. */}
              {COLUMN_HELP[column.id] ? (
                <span className="inline-flex items-center gap-1">
                  {COLUMN_LABELS[column.id]}
                  {/* A legend rather than a tooltip — see StatusHelp for why
                      five definitions are the wrong thing to put in one. */}
                  <StatusHelp />
                </span>
              ) : (
                COLUMN_LABELS[column.id]
              )}
            </TableHead>
          ))}
        </TableRow>
      </TableHeader>

      <TableBody>
        {calls.map((call) => (
          <TableRow
            className="cursor-pointer transition-colors duration-150 ease-out-cubic hover:bg-muted/50 motion-reduce:transition-none"
            key={call.id}
            onClick={() => {
              onCallClick(call)
            }}
          >
            {shown.map((column) => (
              <TableCell key={column.id}>
                <Cell
                  call={call}
                  column={column.id}
                  marker={column.id === "time" ? rowMarker?.(call) : null}
                />
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  )
}

/**
 * One placeholder for every cell that has no value, so a blank never has to be
 * interpreted. Direction used to render nothing at all on a chat row while
 * Phone Number rendered "-" — two ways of saying "no value here" in one row.
 *
 * The two verdict columns keep their own wording, because there the absence
 * *is* a reading: Unavailable is one of the things each of them reports.
 */
function NoValue() {
  return (
    <span aria-label="Not applicable" className="text-muted-foreground">
      —
    </span>
  )
}

function Cell({
  call,
  column,
  marker,
}: {
  call: CallRow
  column: ColumnId
  /** Rendered against the time icon; positioned by whoever passes it. */
  marker?: ReactNode
}) {
  switch (column) {
    case "direction":
      return call.direction ? (
        <DirectionChip direction={call.direction} />
      ) : (
        <NoValue />
      )

    case "duration":
      return call.duration === "-" ? (
        <NoValue />
      ) : (
        <span className="text-sm font-medium text-foreground">
          {call.duration}
        </span>
      )

    /* The chip is the verdict; the tooltip is why it reads that way, and only
       a call that produced one has a why to give. */
    case "outcome":
      return call.outcomeReason ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <span>
              <OutcomeBadge status={call.outcome} />
            </span>
          </TooltipTrigger>
          <TooltipContent>
            <p className="max-w-xs">{call.outcomeReason}</p>
          </TooltipContent>
        </Tooltip>
      ) : (
        <OutcomeBadge status={call.outcome} />
      )

    case "agentOutcome":
      return <AgentOutcomeBadge status={call.agentOutcome} />

    case "phoneNumber":
      return call.phoneNumber ? (
        <span className="text-sm font-medium text-foreground">
          {call.phoneNumber}
        </span>
      ) : (
        <NoValue />
      )

    case "scenario":
      return <ScenarioChip scenario={call.scenario} />

    case "status":
      return (
        <StatusBadge
          scheduleOrigin={call.scheduleOrigin}
          status={call.status}
        />
      )

    case "time":
      return (
        <div className="flex items-center text-muted-foreground">
          <span className="relative me-2 flex">
            <TimeIcon className="size-3.5" />
            {marker}
          </span>
          <span className="text-sm">{call.createdAt}</span>
        </div>
      )
  }
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import {
  COLUMN_LABELS,
  DEFAULT_COLUMNS,
  type ColumnId,
  type ColumnSetting,
} from "@/lib/conversations-revamp-list-data"
import {
  DragHandleIcon,
  FieldsIcon,
} from "@/components/conversations-revamp/list/icons"

/**
 * Which columns the table shows, and in what order.
 *
 * This is what replaced the Default View / Detailed View picker. Two saved
 * views could not answer the questions people actually bring to this table, and
 * a third view per question is how a picker turns into a menu nobody reads —
 * so the columns are chosen directly instead.
 *
 * Drag to reorder, tick to show. The same interaction as the call drawer's
 * panel, because it is the same decision: what belongs on screen, and where.
 */
export function FieldsDropdown({
  columns,
  onChange,
}: {
  columns: ColumnSetting[]
  onChange: (columns: ColumnSetting[]) => void
}) {
  const [dragging, setDragging] = React.useState<ColumnId | null>(null)
  /** Where the dragged row would land — the index the drop line sits before. */
  const [dropAt, setDropAt] = React.useState<null | number>(null)

  const shown = columns.filter((column) => column.visible).length

  function move(from: number, to: number) {
    if (to < 0 || to >= columns.length || from === to) return
    const next = [...columns]
    const [moved] = next.splice(from, 1)
    next.splice(to, 0, moved)
    onChange(next)
  }

  /** Drop uses an insertion point, which shifts once the row is lifted out. */
  function moveTo(from: number, insertAt: number) {
    const next = [...columns]
    const [moved] = next.splice(from, 1)
    next.splice(insertAt > from ? insertAt - 1 : insertAt, 0, moved)
    onChange(next)
  }

  function toggle(id: ColumnId) {
    onChange(
      columns.map((column) =>
        column.id === id ? { ...column, visible: !column.visible } : column,
      ),
    )
  }

  function endDrag() {
    setDragging(null)
    setDropAt(null)
  }

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          aria-label="Choose fields"
          className="bg-card font-normal"
          variant="outline"
        >
          <FieldsIcon className="text-muted-foreground" />
          Fields
          {shown < columns.length ? (
            <span className="text-muted-foreground">
              {shown}/{columns.length}
            </span>
          ) : null}
        </Button>
      </PopoverTrigger>

      <PopoverContent align="end" className="flex w-64 flex-col gap-3">
        <div className="flex flex-col gap-0.5">
          <span className="text-sm font-medium">Fields</span>
          <span className="text-sm text-muted-foreground">
            Drag to reorder. Untick to take a column off the table.
          </span>
        </div>

        <div className="flex flex-col">
          {columns.map((column, index) => (
            <div
              className={cn(
                "relative flex items-center gap-2 rounded-lg py-1 pe-2 transition-opacity duration-150 ease-out-cubic motion-reduce:transition-none",
                dragging === column.id && "opacity-40",
              )}
              draggable
              key={column.id}
              onDragEnd={endDrag}
              onDragOver={(event) => {
                event.preventDefault()
                // Past the midpoint means it lands after this row, not before.
                const box = event.currentTarget.getBoundingClientRect()
                const below = event.clientY > box.top + box.height / 2
                setDropAt(below ? index + 1 : index)
              }}
              onDragStart={() => {
                setDragging(column.id)
              }}
              onDrop={() => {
                const from = columns.findIndex((entry) => entry.id === dragging)
                if (from !== -1 && dropAt !== null) moveTo(from, dropAt)
                endDrag()
              }}
            >
              {/* Absolutely positioned so showing it does not shove the rows
                  around while you are still dragging. */}
              {dropAt === index ? <DropLine className="-top-px" /> : null}
              {dropAt === columns.length && index === columns.length - 1 ? (
                <DropLine className="-bottom-px" />
              ) : null}

              {/* A button, not just the glyph: dragging has no keyboard
                  equivalent, so the handle takes arrow keys itself. */}
              <Button
                aria-label={`Reorder ${COLUMN_LABELS[column.id]}`}
                className="shrink-0 cursor-grab text-muted-foreground"
                onKeyDown={(event) => {
                  if (event.key === "ArrowUp") {
                    event.preventDefault()
                    move(index, index - 1)
                  }
                  if (event.key === "ArrowDown") {
                    event.preventDefault()
                    move(index, index + 1)
                  }
                }}
                size="icon-xs"
                variant="ghost"
              >
                <DragHandleIcon />
              </Button>

              <span className="flex-1 truncate text-sm">
                {COLUMN_LABELS[column.id]}
              </span>

              <Checkbox
                aria-label={`Show ${COLUMN_LABELS[column.id]}`}
                checked={column.visible}
                onCheckedChange={() => {
                  toggle(column.id)
                }}
              />
            </div>
          ))}
        </div>

        <Button
          className="self-end"
          onClick={() => {
            onChange(DEFAULT_COLUMNS)
          }}
          size="sm"
          variant="ghost"
        >
          Reset
        </Button>
      </PopoverContent>
    </Popover>
  )
}

/** Where the dragged row will land. */
function DropLine({ className }: { className: string }) {
  return (
    <span
      className={cn(
        "pointer-events-none absolute inset-x-0 h-0.5 rounded-sm bg-primary",
        className,
      )}
    />
  )
}

