"use client"

import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"
import {
  SCHEDULE_ORIGIN_LABELS,
  type AgentOutcomeStatus,
  type CallDirection,
  type CallStatus,
  type OutcomeStatus,
  type ScheduleOrigin,
} from "@/lib/conversations-revamp-list-data"
import {
  CalendarIcon,
  CompletedIcon,
  FailureIcon,
  HelpfulIcon,
  InboundIcon,
  NoticeIcon,
  NotAnsweredIcon,
  NotHelpfulIcon,
  OutboundIcon,
  RunningIcon,
  TimeIcon,
  VoicemailIcon,
  CallOutgoingIcon,
} from "@/components/conversations-revamp/list/icons"

/**
 * Every chip in the table, from one place.
 *
 * Two rules, and they are what keeps a row readable at a glance:
 *
 *   Size    Every chip is a `<Badge>` with no size classes of its own, so they
 *           all share one height, one radius and one text size. The chips used
 *           to be four hand-rolled spans with three paddings and two radii
 *           between them, which is why a row read as five different components.
 *
 *   Colour  Colour means state. Direction and Scenario are categories — what
 *           kind of thing this is, not how it went — so they stay neutral and
 *           tell themselves apart by their icon. The three verdict chips —
 *           Call status, Outcome, Agent outcome — are the only coloured ones
 *           in a row.
 */

/** The readings a chip can carry. Anything else is `neutral`. */
type Tone = "danger" | "neutral" | "scheduled" | "success" | "warning"

const TONE: Record<Tone, string> = {
  danger: "bg-destructive-tint text-destructive-tint-foreground",
  neutral: "bg-muted text-muted-foreground",
  /* Booked for later. Brand tint: deliberate, and not yet the platform's turn. */
  scheduled: "bg-primary-tint text-primary-tint-foreground",
  success: "bg-success-tint text-success-tint-foreground",
  /* Amber: not settled yet — a call still on its way to finishing. It is not a
     failure, and every actual failure in a row is red. */
  warning: "bg-warning-tint text-warning-tint-foreground",
}

/**
 * The one chip. `variant="secondary"` is only there to drop the default
 * primary fill — the tone class supplies the surface and its foreground.
 */
function Chip({
  children,
  className,
  tone = "neutral",
}: {
  children: React.ReactNode
  className?: string
  tone?: Tone
}) {
  return (
    <Badge className={cn(TONE[tone], className)} variant="secondary">
      {children}
    </Badge>
  )
}

/**
 * What the Status column prints.
 *
 * The raw enum has fifteen values, and reading a column of them meant learning
 * which of `timeout`, `expired`, `user_rejected` and `max_duration_reached`
 * were the same kind of bad. They are: the call did not happen. So the chip
 * leads with the state — Queued, Scheduled, Completed, Failed — and keeps the
 * specific cause after a dash, where it explains rather than competes.
 *
 * Four states, four colours, each answering a different question: amber has
 * not finished, brand tint is booked for later, green worked, red did not.
 * A call on the line is amber too, because from the reader's side the only
 * thing that separates it from a queued one is that there is nothing to open
 * yet either way.
 */
const STATUS_DISPLAY: Record<
  CallStatus,
  { label: string; reason: null | string; tone: Tone }
> = {
  cancelled: { label: "Failed", reason: "cancelled", tone: "danger" },
  completed: { label: "Completed", reason: null, tone: "success" },
  dialing: { label: "Queued", reason: "dialing", tone: "warning" },
  expired: { label: "Failed", reason: "expired", tone: "danger" },
  failed: { label: "Failed", reason: null, tone: "danger" },
  /* Its own state, not a cause of being queued. The dash slot carries why a
     call ended the way it did; "on the call" is not that, and calling a live
     call Queued put it back in a line it had already left. */
  in_progress: { label: "In progress", reason: null, tone: "warning" },
  max_duration_reached: {
    label: "Failed",
    reason: "max duration reached",
    tone: "danger",
  },
  queued: { label: "Queued", reason: null, tone: "warning" },
  ringing: { label: "Queued", reason: "ringing", tone: "warning" },
  scheduled: { label: "Scheduled", reason: null, tone: "scheduled" },
  timeout: { label: "Failed", reason: "not answered", tone: "danger" },
  transferred: { label: "Completed", reason: "transferred", tone: "success" },
  transferring: {
    label: "In progress",
    reason: "transferring",
    tone: "warning",
  },
  user_rejected: { label: "Failed", reason: "user rejected", tone: "danger" },
  voicemail: { label: "Failed", reason: "voicemail", tone: "danger" },
}

function StatusIcon({ status }: { status: CallStatus }) {
  switch (status) {
    case "completed":
      return <CompletedIcon />
    case "in_progress":
    case "dialing":
      return <RunningIcon />
    case "transferring":
    case "transferred":
      return <CallOutgoingIcon />
    case "timeout":
    case "expired":
    case "user_rejected":
    case "cancelled":
      return <NotAnsweredIcon />
    case "queued":
    case "ringing":
      return <TimeIcon />
    case "scheduled":
      return <CalendarIcon />
    case "voicemail":
      return <VoicemailIcon />
    default:
      return <NoticeIcon />
  }
}

export function StatusBadge({
  scheduleOrigin,
  status,
}: {
  /** Splits Scheduled in two, since the two are not the same commitment. */
  scheduleOrigin?: ScheduleOrigin
  status: CallStatus
}) {
  const { label, reason, tone } = STATUS_DISPLAY[status]

  /* Scheduled reads the same whether the analyst guessed at the callback or
     the customer asked for one, and they are not the same thing to act on: one
     is a commitment made to a person, the other is a suggestion. The dash slot
     the other statuses use for their cause carries it. */
  const cause =
    status === "scheduled" && scheduleOrigin
      ? SCHEDULE_ORIGIN_LABELS[scheduleOrigin]
      : reason

  return (
    <Chip tone={tone}>
      <StatusIcon status={status} />
      {label}
      {/* The cause rides inside the same chip, dimmed against its own
          foreground, so the column still scans as four states. */}
      {cause ? <span className="opacity-70">– {cause}</span> : null}
    </Chip>
  )
}

/**
 * Did the scenario's goal get met.
 *
 * One axis, two readings and the absence of one. `Unavailable` is neutral on
 * purpose: no verdict is not a bad verdict, and a queued call dressed in red
 * reads as a call that went wrong. The column used to print `success`,
 * `failure` and `error`, which read as three points on a scale and left the
 * reader deciding whether an errored report was worse than a failed one.
 */
/** The table cell shows the verdict; the reason is in its tooltip. */
export function OutcomeBadge({ status }: { status: OutcomeStatus }) {
  if (status === "unavailable") return <NoVerdict />

  return status === "met" ? (
    <Chip tone="success">
      <CompletedIcon />
      Met
    </Chip>
  ) : (
    <Chip tone="danger">
      <FailureIcon />
      Not met
    </Chip>
  )
}

/**
 * Was the agent any use to the person on the line — a different question from
 * whether the goal was met, which is why it is a different column and a
 * different vocabulary. An agent can be helpful on a call whose goal was never
 * reachable, and useless on one that got there anyway.
 */
export function AgentOutcomeBadge({ status }: { status: AgentOutcomeStatus }) {
  if (status === "unavailable") return <NoVerdict />

  return status === "helpful" ? (
    <Chip tone="success">
      <HelpfulIcon />
      Helpful
    </Chip>
  ) : (
    <Chip tone="danger">
      <NotHelpfulIcon />
      Not helpful
    </Chip>
  )
}

/**
 * What both verdict columns print when there is nothing to report yet.
 *
 * Not a chip: a chip is a reading, and a queued call sitting under two grey
 * pills reads as a call that was judged twice and came back grey. Plain muted
 * text says the same word without competing with the rows that did get a
 * verdict.
 */
function NoVerdict() {
  return <span className="text-sm text-muted-foreground">Unavailable</span>
}

/** A category, so the arrow does the work the colour used to do. */
export function DirectionChip({ direction }: { direction: CallDirection }) {
  return (
    <Chip>
      {direction === "inbound" ? <InboundIcon /> : <OutboundIcon />}
      {direction}
    </Chip>
  )
}

/**
 * A name, not a state. It carries no icon because the name is already the
 * distinguishing thing, and it is the one chip whose width varies with content.
 */
export function ScenarioChip({ scenario }: { scenario: string }) {
  return <Chip className="max-w-50 truncate">{scenario}</Chip>
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import {
  STATUS_GROUPS,
  type StatusGroupId,
} from "@/lib/conversations-revamp-list-data"
import {
  ChevronDownIcon,
  SelectedIcon,
} from "@/components/conversations-revamp/list/icons"

/**
 * The Status filter: a trigger that reads "Status" until something is ticked
 * and then "N selected", over the four groups with a Clear All footer. Applies
 * as you tick — there is no Apply button on this one.
 *
 * Five rows rather than fifteen. `STATUS_GROUPS` says why, and holds the raw
 * statuses each one stands for.
 */
export function StatusFilter({
  defaultOpen = false,
}: {
  /** Opens the list on load, so the dropdown has a link of its own. */
  defaultOpen?: boolean
}) {
  const [open, setOpen] = React.useState(defaultOpen)
  const [selected, setSelected] = React.useState<StatusGroupId[]>([])

  function toggle(group: StatusGroupId) {
    setSelected((current) =>
      current.includes(group)
        ? current.filter((item) => item !== group)
        : [...current, group],
    )
  }

  return (
    <Popover onOpenChange={setOpen} open={open}>
      <PopoverTrigger asChild>
        <Button
          aria-expanded={open}
          aria-label="Select Status"
          className={cn(
            "w-32 justify-between bg-card font-normal",
            !selected.length && "text-muted-foreground",
          )}
          variant="outline"
        >
          <span className="truncate">
            {selected.length === 0 ? (
              "Status"
            ) : selected.length === 1 ? (
              STATUS_GROUPS.find((group) => group.id === selected[0])?.label
            ) : (
              <span className="flex items-center gap-1.5">
                <span className="font-medium">{selected.length}</span>
                <span className="text-muted-foreground">selected</span>
              </span>
            )}
          </span>
          <ChevronDownIcon
            className={cn(
              "ms-2 shrink-0 opacity-50 transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
              open && "rotate-180",
            )}
          />
        </Button>
      </PopoverTrigger>

      <PopoverContent align="start" className="w-56 overflow-hidden p-0">
        <div className="flex flex-col">
          {/* Five rows still fit without scrolling, so the list needs no
              height cap and no inner scroller. */}
          <div className="p-1">
            {STATUS_GROUPS.map((group) => {
              const isSelected = selected.includes(group.id)

              return (
                <div
                  className={cn(
                    "flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 hover:bg-accent",
                    isSelected && "bg-accent/50",
                  )}
                  key={group.id}
                  onClick={() => {
                    toggle(group.id)
                  }}
                >
                  <Checkbox
                    checked={isSelected}
                    className="pointer-events-none"
                  />
                  <span className="flex-1 cursor-pointer text-sm">
                    {group.label}
                  </span>
                  {isSelected ? (
                    <SelectedIcon className="size-4 text-primary opacity-50" />
                  ) : null}
                </div>
              )
            })}
          </div>

          <div className="shrink-0 border-t p-2">
            <div className="flex gap-2">
              <Button
                className="flex-1"
                onClick={() => {
                  setSelected([])
                }}
                size="sm"
                variant="ghost"
              >
                Clear All
              </Button>
            </div>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  )
}

"use client"

import { useSyncExternalStore } from "react"

import { VercelToolbar } from "@vercel/toolbar/next"

/** Survives a reload, so a reviewer opts in once rather than per link. */
const STORAGE_KEY = "sarj-mockups:toolbar"

/* Two components read this store — the toolbar itself and the toggle in the
   shell header — and a write from one has to reach the other. `storage` only
   fires in the *other* tabs, so same-tab writes are fanned out here. */
const listeners = new Set<() => void>()

function emit() {
  for (const listener of listeners) listener()
}

let applied = false

/**
 * Applies `?toolbar=1` / `?toolbar=0` to the stored value, once per load
 * rather than once per subscriber — the flag is a property of the URL, not of
 * whichever component happened to mount first.
 *
 * Returns whether there was a flag to apply, since React reads the snapshot
 * before it subscribes and needs telling if that read is already stale.
 */
function applyUrlFlag() {
  if (applied) return false
  applied = true

  const flag = new URLSearchParams(window.location.search).get("toolbar")

  if (flag === "1") window.localStorage.setItem(STORAGE_KEY, "on")
  if (flag === "0") window.localStorage.removeItem(STORAGE_KEY)

  return Boolean(flag)
}

function subscribe(onStoreChange: () => void) {
  listeners.add(onStoreChange)

  if (applyUrlFlag()) onStoreChange()

  /* Another tab changing the flag turns the toolbar on here too. */
  window.addEventListener("storage", onStoreChange)

  return () => {
    listeners.delete(onStoreChange)
    window.removeEventListener("storage", onStoreChange)
  }
}

function getSnapshot() {
  return window.localStorage.getItem(STORAGE_KEY) === "on"
}

/** Nothing is opted in on the server, so the static HTML never carries it. */
function getServerSnapshot() {
  return false
}

function getSuppressedSnapshot() {
  return new URLSearchParams(window.location.search).get("toolbar") === "0"
}

function getSuppressedServerSnapshot() {
  return false
}

/** Whether the toolbar is on, for anything that has to reflect that state. */
export function useToolbarEnabled() {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot)
}

/**
 * `?toolbar=0` hides the toggle as well as the toolbar: no toolbar, and nothing
 * offering to turn one on. `npm run shots` and `npm run thumbs` drive every
 * route with it, so a capture carries the design and not the chrome around it.
 */
export function useToolbarSuppressed() {
  return useSyncExternalStore(
    subscribe,
    getSuppressedSnapshot,
    getSuppressedServerSnapshot,
  )
}

/**
 * Turns the toolbar on or off from inside the page.
 *
 * `replaceState` rather than a navigation: the store already drives the
 * toolbar, so a reload would buy nothing but a round trip. The flag still goes
 * into the address bar, because that is what makes the URL worth copying — the
 * next reviewer gets a link that arrives already opted in.
 */
export function setToolbar(on: boolean) {
  if (on) window.localStorage.setItem(STORAGE_KEY, "on")
  else window.localStorage.removeItem(STORAGE_KEY)

  const url = new URL(window.location.href)

  if (on) url.searchParams.set("toolbar", "1")
  else url.searchParams.delete("toolbar")

  window.history.replaceState(null, "", url)

  emit()
}

/**
 * The Vercel toolbar — and with it Comments — on the deployed site.
 *
 * Preview deployments get the toolbar for free; this is for the production
 * URL, which is the one people are actually sent. It is deliberately behind a
 * flag: mounting the toolbar unconditionally prompts *every* visitor to log in
 * to Vercel, and this site answers unauthenticated requests. A reviewer turns
 * it on from the shell header; nobody else is asked for anything.
 *
 * Read through `useSyncExternalStore` rather than an effect so no route has to
 * give up static rendering, and so the flag is read the way any other external
 * store would be.
 */
export function StaffToolbar() {
  const enabled = useToolbarEnabled()

  return enabled ? <VercelToolbar /> : null
}

